import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a,a as o}from"./chunks/qr_libre2direct-calib-30.qmCsLi9X.js";import{_ as t,o as r,c as n,a3 as s}from"./chunks/framework.g9mfNVRQ.js";const v=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{"source_hash":"03b49989fb","source_commit":"e9ebf28"},"headers":[],"relativePath":"it/install/libre2.md","filePath":"it/install/libre2.md"}'),l={name:"it/install/libre2.md"};function c(p,i,d,u,m,h){return r(),n("div",null,[...i[0]||(i[0]=[s('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Libre Bluetooth</p></div><h3 id="libre-2-direct" tabindex="-1">Libre 2 Direct <a class="header-anchor" href="#libre-2-direct" aria-label="Permalink to &quot;Libre 2 Direct {#libre-2-direct}&quot;">​</a></h3><p>Questa pagina descrive come attivare la connessione Bluetooth diretta tra il sensore e xDrip, senza bisogno di un bridge.</p><h4 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h4><p>Il telefono su cui hai installato xDrip ha un lettore NFC.</p><p>Se l&#39;app del produttore è installata sullo stesso telefono che usi per xDrip, <strong>l&#39;hai disinstallata</strong>.<br> Se è installata su un altro telefono o usi il lettore Bluetooth, hai allontanato questi dispositivi, o li hai schermati, in modo che non interferiscano.</p><h4 id="setting-up-for-the-first-time" tabindex="-1">Prima configurazione <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Prima configurazione {#setting-up-for-the-first-time}&quot;">​</a></h4><p>(Clicca <a href="#starting-libre-2-sensors">Inizializza Sensore</a> per i sensori successivi).</p><div class="info custom-block"><p class="custom-block-title">Sono supportati solo i modelli di sensore Libre 2/2+ europei</p><p>Devi installare l&#39;<a href="./../use/OOP.html#oop2">ultima versione dell&#39;app OOP2</a>.</p></div><p>La documentazione di riferimento di Libre 2 si trova <a href="https://www.minimallooper.com/post/how-to-setup-freestyle-libre-2-and-oop2-to-use-a-native-bluetooth-connection-in-xdrip" target="_blank" rel="noreferrer">qui</a>, ma non è più aggiornata.</p><br><div class="warning custom-block"><p class="custom-block-title">Attenzione</p><p><strong>Disinstalla tutte le app collegate al sensore e scherma il lettore prima di provare a collegarlo a xDrip.</strong><br> Se colleghi il sensore direttamente a xDrip perderai definitivamente gli allarmi dell&#39;app del produttore o del lettore, senza possibilità di recuperarli.<br> Se non sei sicuro che funzioni, usa un sensore a fine vita per provare il sistema.<br> Come per i bridge Libre, il successo e l&#39;affidabilità variano a seconda del telefono.<br> Collegare il sensore a xDrip annulla la garanzia del produttore sulla funzione Bluetooth del sensore.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurare xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurare xDrip {#setup-xdrip}&quot;">​</a></h4><p>Come scorciatoia, puoi scansionare il codice QR qui sotto per caricare le impostazioni necessarie per Libre 2/2+ diretto con la funzione <a href="./../use/copysettings.html#auto-configure">Configurazione automatica</a> di xDrip. Se stai consultando la documentazione dal telefono su cui installi xDrip, salva prima le immagini e poi caricale con la funzione &quot;File immagine&quot; della configurazione automatica.</p><p>Impostano la <strong><a href="./../use/misc.html#oop2">calibrazione disattivata</a>, consigliata per il primo utilizzo</strong>. Se invece vuoi la calibrazione, <a href="./libre2direct-calib.html">segui queste istruzioni</a>. L&#39;elenco completo delle impostazioni importate è <a href="./libre2direct-qr-settings.html">qui</a>.</p><p>Codici QR - Clicca sull&#39;immagine per ingrandirla</p><table tabindex="0"><thead><tr><th style="text-align:center;">Senza calibrazione</th><th style="text-align:center;">Con calibrazione</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./libre2direct-qr-settings.html"><img src="'+a+'" style="zoom:50%;"></a></td><td style="text-align:center;"><a href="./libre2direct-calib.html"><img src="'+o+'" style="zoom:50%;"></a></td></tr></tbody></table><p>Se hai usato i codici QR, puoi passare direttamente ad <a href="#starting-libre-2-sensors">Avviare i sensori Libre 2</a></p><h4 id="configure-nfc" tabindex="-1">Configurare l&#39;NFC <a class="header-anchor" href="#configure-nfc" aria-label="Permalink to &quot;Configurare l&#39;NFC {#configure-nfc}&quot;">​</a></h4><p>Configura l&#39;NFC esattamente <a href="./../use/NFC.html">come qui</a>.</p><h4 id="starting-libre-2-sensors" tabindex="-1">Avviare i sensori Libre 2 <a class="header-anchor" href="#starting-libre-2-sensors" aria-label="Permalink to &quot;Avviare i sensori Libre 2 {#starting-libre-2-sensors}&quot;">​</a></h4><p>Applica fisicamente il sensore Libre 2/2+ e avvialo con il lettore oppure con LibreLink. Annota l&#39;ora in cui il sensore sarà pronto. Se usi lo stesso telefono di xDrip, disattiva LibreLink sul telefono. Scansionandolo dovresti vedere i valori di glicemia. Ora attendi 60 minuti, finché il sensore ha terminato il riscaldamento e si è autocalibrato.</p><h4 id="connect-to-the-sensor" tabindex="-1">Collegarsi al sensore <a class="header-anchor" href="#connect-to-the-sensor" aria-label="Permalink to &quot;Collegarsi al sensore {#connect-to-the-sensor}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Stop Sensore</p></div><p>Se a xDrip è collegato un sensore precedente, ferma il vecchio sensore.</p><p>Scansiona il sensore con l&#39;NFC di xDrip e verifica di vedere i messaggi &quot;Scansione in corso..&quot; e poi &quot;Scansionato OK!&quot;.</p><div class="info custom-block"><p class="custom-block-title">Nota</p><p>Tieni il telefono fermo durante la scansione del sensore e non muoverlo: ci vuole più tempo rispetto alla lettura che fai di solito con l&#39;app del produttore.<br> Ricorda che devi attendere un minuto tra due scansioni NFC consecutive.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Inizializza Sensore</p></div><p>Avvia il sensore in xDrip. Quando ti viene chiesto di inserire l&#39;ora in cui hai avviato fisicamente il sensore, non indicare un&#39;ora precedente a quella reale, per evitare valori incoerenti.</p><p>Attendi 60 secondi e scansiona di nuovo con xDrip. In questo modo il sensore viene aggiunto come dispositivo BT da cui xDrip riceverà le letture. Dovresti vedere la notifica NUOVO SENSOR AVVIATO. Se hai impostato &quot;Nessuna calibrazione&quot;, dovresti vedere subito la prima lettura. Se hai impostato la calibrazione, dovresti trovarti nella schermata &quot;Sto raccogliendo le prime letture&quot;. Ora dovrai attendere tra 3 e 15 minuti per ricevere 3 letture, poi verrà mostrata la richiesta <strong>Calibrare il sensore?</strong>, a meno che tu non abbia selezionato &quot;Nessuna calibrazione&quot; nelle <a href="./../use/misc.html#oop2">impostazioni OOP2</a>. Dopo aver inserito i dati di calibrazione, il sensore Libre 2/2+ dovrebbe essere associato a xDrip e fornire letture ogni 5 minuti.</p><p>Puoi verificare che tutto funzioni confrontando con &quot;Come dovrebbe apparire&quot; <a href="./../troubleshoot/libre2direct.html#what-it-should-look-like">qui</a></p><p>Se hai difficoltà a ricevere dati direttamente dal sensore, scansionalo ogni 5 minuti con l&#39;NFC di xDrip fino ad arrivare alla richiesta di calibrazione (vale se hai selezionato l&#39;<a href="./../use/misc.html#oop2">opzione di calibrazione</a> con OOP2).</p><br><h4 id="problems" tabindex="-1"><strong>Problemi?</strong> <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;**Problemi?** {#problems}&quot;">​</a></h4><p>Consulta la pagina di <a href="./../troubleshoot/libre2direct.html">risoluzione problemi</a>.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Ultima modifica 7/12/2024</em></a></p>',37)])])}const z=t(l,[["render",c]]);export{v as __pageData,z as default};
